  'Cuma' => 'viernes',
  'Cumartesi' => 'sábado',
  'Pazar' => 'domingo',
  '[%1$s] Site denetimi: %2$d yeni kritik/yüksek öneri' => '[%1$s] Auditoría del sitio:%2$dnuevas recomendaciones críticas/altas',
  'Otomatik site denetiminde yeni öneriler çıktı:' => 'La auditoría automática del sitio encontró nuevas recomendaciones:',
