  'Ayırıcı' => 'Separador',
  'Bulgu yok' => 'Sin hallazgos',
  'Bulgular' => 'Hallazgos',
  'Denetim e-postası' => 'Auditoría de correo electrónico',
  'Denetim güncellendi' => 'Auditoría actualizada',
  'Denetim sıklığı' => 'cronograma de auditoría',
  'Denetim çalışınca bulgular burada listelenir.' => 'Los hallazgos aparecen aquí después de ejecutar una auditoría.',
  'Denetimi çalıştır' => 'Ejecutar auditoría',
  'E-posta' => 'Correo electrónico',
  'Etiketleri dizine ekleme' => 'No indexar etiquetas',
